import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { ArrowUpRight, ArrowRight, ArrowLeft, Search, MapPin, ChevronDown, ChevronRight, Heart, Star, Utensils, Coffee, Flame, Pizza, Beer, IceCream, Croissant, Fish, SlidersHorizontal, X, Menu, Check, CheckCircle2, Plus, Mail, Clock, Waves, Leaf, PawPrint, Accessibility, Sun, Store, MessageSquare, ShieldCheck, LogOut, Pencil, Trash2, Send, Compass, Eye, Users, Sparkles, CalendarDays, CircleHelp, Image as ImageIcon } from 'lucide-react';
import { categorias, localidades, prestaciones, negocios, imagenes, opinionesIniciales, filtrarNegocios } from './datos.js';
import { supabase, conectado, traducirError } from './supabase.js';

const Contexto=createContext(null);
const usar=()=>useContext(Contexto);
const usarCategorias=()=>usar()?.todasCategorias||categorias;
const iconos={utensils:Utensils,coffee:Coffee,flame:Flame,pizza:Pizza,beer:Beer,icecream:IceCream,croissant:Croissant,fish:Fish};
const puntuacionLocal=valor=>Number(valor||0).toLocaleString('es-AR',{minimumFractionDigits:1,maximumFractionDigits:1});
const formatear=fecha=>new Date(fecha+'T12:00:00').toLocaleDateString('es-AR',{day:'numeric',month:'long',year:'numeric'});
const slugificar=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const vacios={negocios:[],opiniones:[],consultas:[],reclamos:[],categorias:[]};
function Enlace({to,children,className='',...rest}){const {ir}=usar();return <a href={to} className={className} onClick={e=>{if(!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();ir(to);}}} {...rest}>{children}</a>}
function IconoCategoria({id,...props}){const Icono=iconos[categorias.find(c=>c.id===id)?.icono]||Utensils;return <Icono {...props}/>}
function Estrellas({valor}){return <span className="puntuacion"><Star size={13} fill="currentColor"/>{puntuacionLocal(valor)}</span>}
function Logo(){return <Enlace to="/" className="marca" aria-label="Costa a la carta, inicio"><span className="marca-icono"><Utensils size={24}/></span><span>Costa <em>a la carta</em><small>SABORES DE NUESTRA COSTA</small></span></Enlace>}
function BotonFavorito({id,grande=false}){const {favoritos,alternarFavorito}=usar();const activo=favoritos.includes(id);return <button className={`favorito ${grande?'grande':''} ${activo?'activo':''}`} onClick={()=>alternarFavorito(id)} aria-label={activo?'Quitar de mis guardados':'Guardar lugar'} aria-pressed={activo}><Heart size={19} fill={activo?'currentColor':'none'}/>{grande&&(activo?'Guardado':'Guardar')}</button>}
function Tarjeta({negocio:n}){const categorias=usarCategorias();return <article className="tarjeta"><Enlace to={'/lugar/'+n.slug} className="tarjeta-foto"><img src={n.imagen} alt={`${n.nombre}: ${categorias.find(c=>c.id===n.categoria)?.nombre} en ${n.localidad}`} loading="lazy"/>{n.destacado&&<span className="distintivo"><Sparkles size={12}/> Destacado</span>}</Enlace><BotonFavorito id={n.id}/><div className="tarjeta-cuerpo"><div className="tarjeta-meta"><Enlace to={'/categoria/'+n.categoria}>{categorias.find(c=>c.id===n.categoria)?.nombre||n.categoria}</Enlace><span>{'$'.repeat(n.precio)}</span></div><div className="tarjeta-titulo"><h3><Enlace to={'/lugar/'+n.slug}>{n.nombre}</Enlace></h3><Estrellas valor={n.valoracion}/></div><p className="ubicacion"><MapPin size={13}/>{n.localidad}</p><p className="tarjeta-descripcion">{n.descripcion}</p><div className="tarjeta-pie"><span>{n.prestaciones.includes('Mesas al aire libre')?<><Sun size={13}/>Al aire libre</>:n.prestaciones.includes('Opciones vegetarianas')?<><Leaf size={13}/>Opciones vegetarianas</>:<><Utensils size={13}/>Sabores locales</>}</span><Enlace to={'/lugar/'+n.slug} aria-label={'Conocer '+n.nombre}><ArrowUpRight size={19}/></Enlace></div></div></article>}
function Cabecera(){const {ruta,usuario,modoDemo}=usar();const [menu,setMenu]=useState(false);useEffect(()=>setMenu(false),[ruta]);return <header className="cabecera"><div className="contenedor cabecera-interior"><Logo/><nav className={menu?'navegacion abierta':'navegacion'} aria-label="Navegación principal"><Enlace to="/explorar" className={ruta.startsWith('/explorar')?'seleccionado':''}>Descubrir lugares</Enlace><Enlace to="/categorias" className={ruta.startsWith('/categoria')?'seleccionado':''}>Categorías</Enlace><Enlace to="/sobre-la-costa">Nuestra Costa <ArrowUpRight size={13}/></Enlace></nav><div className="acciones-cabecera"><Enlace to="/guardados" className="enlace-guardados" aria-label="Mis guardados"><Heart size={17}/><span>Mis guardados</span></Enlace><Enlace to="/sumar-lugar" className="boton boton-oscuro boton-chico"><Plus size={15}/>Sumá tu lugar</Enlace><Enlace to={usuario||modoDemo?'/mi-negocio':'/ingresar'} className="acceso" aria-label="Ingresar a mi cuenta"><Users size={18}/></Enlace><button className="menu-movil" aria-label="Abrir menú" aria-expanded={menu} onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></div></header>}
function Buscador({compacto=false}){const {ir}=usar();const [q,setQ]=useState('');const [localidad,setLocalidad]=useState('');return <form className={'buscador '+(compacto?'compacto':'')} onSubmit={e=>{e.preventDefault();const p=new URLSearchParams();if(q.trim())p.set('q',q.trim());if(localidad)p.set('localidad',localidad);ir('/explorar'+(p.size?'?'+p:''));}}><div className="campo-buscar"><Search size={21}/><label><span>¿Qué se te antoja?</span><input aria-label="Qué querés comer" placeholder="Un café, una buena parrilla..." value={q} onChange={e=>setQ(e.target.value)}/></label></div><div className="campo-localidad"><MapPin size={21}/><label><span>¿Por dónde?</span><select aria-label="Elegir localidad" value={localidad} onChange={e=>setLocalidad(e.target.value)}><option value="">Todas las localidades</option>{localidades.map(l=><option key={l}>{l}</option>)}</select></label><ChevronDown size={15}/></div><button className="boton boton-naranja" type="submit"><Search size={17}/>Buscar lugares</button></form>}
function Inicio(){const {listado}=usar();const categorias=usarCategorias();return <><section className="hero"><div className="contenedor hero-interior"><div className="hero-texto"><div className="etiqueta"><span/>BUENOS PLANES, CERCA DEL MAR</div><h1>La Costa tiene<br/>mucho <em>sabor.</em></h1><p>Descubrí esos lugares a los que siempre querés volver.<br className="solo-escritorio"/> Buena comida, gente local y un poquito de mar.</p><div className="hero-detalle"><span className="avatares"><img src="https://i.pravatar.cc/60?img=47" alt=""/><img src="https://i.pravatar.cc/60?img=12" alt=""/><img src="https://i.pravatar.cc/60?img=44" alt=""/></span><span>Hecho para quienes disfrutan<br/><strong>comer bien y descubrir más.</strong></span></div></div><div className="hero-visual"><img className="hero-imagen" src={imagenes.hero} alt="Un restaurante cálido, lleno de plantas y luz natural" fetchPriority="high"/><span className="sello-costero"><Waves size={22}/><span>CON GUSTO<br/>A COSTA</span><small>36° S · 56° O</small></span><div className="hero-nota"><span><Sun size={24}/></span><div>El mejor plan<small>está a la vuelta de la esquina.</small></div><ArrowUpRight size={19}/></div></div><div className="hero-buscador"><Buscador/><div className="sugerencias">Un antojo para empezar:<Enlace to="/categoria/cafeterias">Café de especialidad</Enlace><Enlace to="/categoria/mariscos">Sabores del mar</Enlace><Enlace to="/explorar?prestacion=Mesas+al+aire+libre">Comer al aire libre <ArrowUpRight size={11}/></Enlace></div></div></div></section><section className="seccion categorias-inicio contenedor"><div className="titulo-seccion"><div><span className="sobretitulo">SEGUÍ TU ANTOJO</span><h2>¿Qué tenés ganas de comer?</h2></div><Enlace to="/categorias" className="enlace-flecha">Ver categorías <ArrowRight size={17}/></Enlace></div><div className="fila-categorias">{categorias.map(c=><Enlace to={'/categoria/'+c.id} key={c.id} className="categoria-circulo"><span style={{background:c.color}}><IconoCategoria id={c.id} size={28} strokeWidth={1.45}/></span><strong>{c.nombre}</strong><small>{listado.filter(n=>n.categoria===c.id&&n.estado==='aprobado').length} lugares</small></Enlace>)}</div></section><section className="seccion destacados contenedor"><div className="titulo-seccion"><div><span className="sobretitulo">ESOS LUGARES QUE ENAMORAN</span><h2>Para poner en tu lista <span className="estrellita">✳</span></h2><p>Una selección para comer rico y disfrutar sin apuro.</p></div><Enlace to="/explorar" className="enlace-flecha">Explorar todos los lugares <ArrowRight size={17}/></Enlace></div><div className="grilla-tarjetas">{listado.filter(n=>n.destacado&&n.estado==='aprobado').slice(0,3).map(n=><Tarjeta key={n.id} negocio={n}/>)}</div></section><section className="franja-localidades"><div className="contenedor"><div className="titulo-seccion"><div><span className="sobretitulo">CADA LOCALIDAD, UN NUEVO SABOR</span><h2>Tu próximo plan, en La Costa.</h2></div><MapPin className="mapa-deco" size={39} strokeWidth={1.2}/></div><div className="localidades-pastillas">{localidades.map((l,i)=><Enlace to={'/explorar?localidad='+encodeURIComponent(l)} key={l}>{l}<ArrowUpRight size={15}/></Enlace>)}</div></div></section><section className="seccion contenedor descubrimientos"><div className="titulo-seccion"><div><span className="sobretitulo">HAY MUCHO POR DESCUBRIR</span><h2>Sabores para todos tus planes</h2></div><Enlace to="/explorar" className="enlace-flecha">Encontrá tu lugar <ArrowRight size={17}/></Enlace></div><div className="grilla-tarjetas">{listado.filter(n=>!n.destacado&&n.estado==='aprobado').slice(0,3).map(n=><Tarjeta key={n.id} negocio={n}/>)}</div></section><section className="contenedor"><div className="banner-negocio"><div className="ilustracion-plato"><Utensils size={45} strokeWidth={1}/><span>✳</span></div><div><span className="sobretitulo">LOS BUENOS LUGARES MERECEN SER DESCUBIERTOS</span><h2>¿Tu negocio tiene sabor a Costa?</h2><p>Sumalo al directorio y conectá con quienes buscan su próximo lugar favorito.</p></div><Enlace to="/sumar-lugar" className="boton boton-oscuro">Sumá tu lugar <ArrowUpRight size={17}/></Enlace></div></section></>}
function Pie(){return <footer className="pie"><div className="contenedor"><div className="pie-arriba"><div><Logo/><p>Los sabores, las historias y los lugares<br/>que hacen única a nuestra Costa.</p><span className="hecho"><Waves size={15}/>Hecho con amor por lo local.</span></div><div><strong>A descubrir</strong><Enlace to="/explorar">Todos los lugares</Enlace><Enlace to="/categorias">Categorías</Enlace><Enlace to="/guardados">Mis guardados</Enlace></div><div><strong>Para tu negocio</strong><Enlace to="/sumar-lugar">Sumar un lugar</Enlace><Enlace to="/reclamar">Reclamar mi negocio</Enlace><Enlace to="/mi-negocio">Mi panel</Enlace></div><div><strong>Conocenos</strong><Enlace to="/sobre-la-costa">Nuestra Costa</Enlace><Enlace to="/como-funciona">Cómo funciona</Enlace><Enlace to="/administracion">Administración</Enlace></div></div><div className="pie-abajo"><span>© {new Date().getFullYear()} Costa a la carta. Cada sabor, una historia.</span><span>Edición de muestra · Negocios y reseñas ficticios · Fotos ilustrativas</span></div></div></footer>}
function Migas({items}){return <nav className="migas" aria-label="Ruta de navegación"><Enlace to="/">Inicio</Enlace>{items.map((i,k)=><React.Fragment key={k}><ChevronRight size={12}/>{i.to?<Enlace to={i.to}>{i.texto}</Enlace>:<span>{i.texto}</span>}</React.Fragment>)}</nav>}
function Explorador({categoria}){const {ruta,ir,listado}=usar();const categorias=usarCategorias();const p=new URLSearchParams(ruta.split('?')[1]);const c=categorias.find(c=>c.id===categoria);const [q,setQ]=useState(p.get('q')||'');const [filtrosAbiertos,setFiltrosAbiertos]=useState(false);const [orden,setOrden]=useState('recomendados');useEffect(()=>setQ(p.get('q')||''),[ruta]);const filtros={q:p.get('q')||'',categoria:categoria||p.get('categoria')||'',localidad:p.get('localidad')||'',precio:p.get('precio')||'',valoracion:p.get('valoracion')||'',prestaciones:p.getAll('prestacion')};const cambiar=(clave,valor,multiple=false)=>{const params=new URLSearchParams(ruta.split('?')[1]);if(multiple){const prev=params.getAll(clave);params.delete(clave);(prev.includes(valor)?prev.filter(x=>x!==valor):[...prev,valor]).forEach(v=>params.append(clave,v));}else valor?params.set(clave,valor):params.delete(clave);ir((categoria?'/categoria/'+categoria:'/explorar')+(params.size?'?'+params:''),false);};let resultados=filtrarNegocios(listado,filtros,categorias);resultados=[...resultados].sort(orden==='valoracion'?(a,b)=>b.valoracion-a.valoracion:orden==='precio'?(a,b)=>a.precio-b.precio:(a,b)=>Number(b.destacado)-Number(a.destacado));const num=Object.entries(filtros).filter(([k,v])=>k!=='q'&&k!=='categoria'&&(Array.isArray(v)?v.length:v)).length;return <main className="contenedor pagina explorar"><Migas items={[{texto:c?.nombre||'Descubrir lugares'}]}/><div className="encabezado-pagina"><span className="sobretitulo">{c?'SEGUÍ TU ANTOJO':'UN NUEVO FAVORITO TE ESPERA'}</span><h1>{c?c.nombre+' en La Costa':'Encontrá tu próximo lugar favorito'}</h1><p>{c?c.texto+'. Conocé las propuestas del Partido de La Costa.':'De un café al sol a una cena frente al mar. Elegí tu plan.'}</p></div><form className="buscador-listado" onSubmit={e=>{e.preventDefault();cambiar('q',q);}}><Search size={20}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscá por nombre, comida o localidad" aria-label="Buscar en el directorio"/><button className="boton boton-naranja">Buscar</button></form><div className="explorar-disposicion"><aside className={'filtros '+(filtrosAbiertos?'visible':'')}><div className="filtros-titulo"><h2><SlidersHorizontal size={17}/>Filtrá tu búsqueda</h2><button className="boton-texto" onClick={()=>ir(categoria?'/categoria/'+categoria:'/explorar',false)}>Limpiar</button></div><label className="etiqueta-campo">Localidad<select value={filtros.localidad} onChange={e=>cambiar('localidad',e.target.value)}><option value="">Toda La Costa</option>{localidades.map(l=><option key={l}>{l}</option>)}</select></label>{!categoria&&<label className="etiqueta-campo">Categoría<select value={filtros.categoria} onChange={e=>cambiar('categoria',e.target.value)}><option value="">Todas las categorías</option>{categorias.map(c=><option key={c.id} value={c.id}>{c.nombre}</option>)}</select></label>}<fieldset><legend>Precio por persona</legend><div className="precios">{[1,2,3].map(n=><button key={n} className={filtros.precio===String(n)?'activo':''} aria-pressed={filtros.precio===String(n)} onClick={()=>cambiar('precio',filtros.precio===String(n)?'':n)}>{'$'.repeat(n)}</button>)}</div><small>$ Económico · $$$ Una ocasión especial</small></fieldset><fieldset><legend>Valoración</legend>{['','4','4.5','4.8'].map((v,i)=><label className="checkbox" key={i}><input type="radio" name="valoracion" checked={filtros.valoracion===v} onChange={()=>cambiar('valoracion',v)}/>{v?<><Star size={13}/> {v.replace('.',',')} o más</>:'Todas las valoraciones'}</label>)}</fieldset><fieldset><legend>Para tu plan</legend>{prestaciones.map(pr=><label className="checkbox" key={pr}><input type="checkbox" checked={filtros.prestaciones.includes(pr)} onChange={()=>cambiar('prestacion',pr,true)}/>{pr}</label>)}</fieldset><div className="nota-filtros"><Waves size={23}/><p>Un buen plan empieza<br/>por un buen lugar.</p></div></aside><section className="resultados"><div className="barra-resultados"><span><strong>{resultados.length}</strong> {resultados.length===1?'lugar para descubrir':'lugares para descubrir'}</span><button className="filtros-movil boton boton-borde" onClick={()=>setFiltrosAbiertos(!filtrosAbiertos)}><SlidersHorizontal size={15}/>Filtros {num?`(${num})`:''}</button><label>Ordenar por <select aria-label="Ordenar resultados" value={orden} onChange={e=>setOrden(e.target.value)}><option value="recomendados">Recomendados</option><option value="valoracion">Mejor valorados</option><option value="precio">Menor precio</option></select></label></div>{resultados.length?<div className="grilla-tarjetas dos-columnas">{resultados.map(n=><Tarjeta key={n.id} negocio={n}/>)}</div>:<Vacio icono={Search} titulo="Todavía no encontramos ese sabor" texto="Probá con otra localidad o quitá algún filtro para descubrir más lugares."><button className="boton boton-naranja" onClick={()=>ir('/explorar',false)}>Ver todos los lugares</button></Vacio>}<p className="nota-muestra">Catálogo de demostración: las valoraciones, las direcciones y los negocios son ejemplos ficticios.</p></section></div></main>}
function Vacio({icono:Icono=Compass,titulo,texto,children}){return <div className="estado-vacio"><span><Icono size={32} strokeWidth={1.4}/></span><h2>{titulo}</h2><p>{texto}</p>{children}</div>}
function Categorias(){const {listado}=usar();const categorias=usarCategorias();return <main className="contenedor pagina"><Migas items={[{texto:'Categorías'}]}/><div className="encabezado-pagina"><span className="sobretitulo">PARA TODOS LOS ANTOJOS</span><h1>Cada sabor tiene su lugar.</h1><p>Descubrí La Costa por lo que más te gusta comer.</p></div><div className="grilla-categorias">{categorias.map(c=><Enlace to={'/categoria/'+c.id} key={c.id} className="categoria-grande" style={{background:c.color}}><IconoCategoria id={c.id} size={36} strokeWidth={1.3}/><h2>{c.nombre}</h2><p>{c.texto}.</p><span>{listado.filter(n=>n.categoria===c.id&&n.estado==='aprobado').length} lugares para descubrir <ArrowUpRight size={18}/></span></Enlace>)}</div></main>}
function Detalle({slug}){const categorias=usarCategorias();const {listado,opiniones,modal,setModal,notificar,usuario,modoDemo}=usar();const n=listado.find(n=>n.slug===slug&&n.estado==='aprobado');const [foto,setFoto]=useState(0);useEffect(()=>setFoto(0),[slug]);if(!n)return <NoEncontrado/>;const cat=categorias.find(c=>c.id===n.categoria);const res=opiniones.filter(r=>r.negocio_id===n.id&&r.estado==='aprobado');const relacionados=listado.filter(x=>x.id!==n.id&&x.estado==='aprobado'&&(x.categoria===n.categoria||x.localidad===n.localidad)).slice(0,3);return <main className="contenedor pagina detalle"><Migas items={[{to:'/categoria/'+n.categoria,texto:cat?.nombre},{texto:n.nombre}]}/><div className="detalle-encabezado"><div><span className="sobretitulo">{cat?.nombre} · {'$'.repeat(n.precio)}</span><h1>{n.nombre} {n.destacado&&<span className="distintivo"><Sparkles size={12}/>Destacado</span>}</h1><p className="detalle-localidad"><MapPin size={16}/>{n.localidad}<span>·</span><Estrellas valor={n.valoracion}/><a href="#opiniones">{n.opiniones} valoraciones de muestra</a></p></div><BotonFavorito id={n.id} grande/></div><div className="galeria"><button className="galeria-principal" onClick={()=>setModal({tipo:'imagen',negocio:n,indice:foto})} aria-label="Ampliar foto"><img src={n.galeria?.[foto]||n.imagen} alt={'Interior y propuesta de '+n.nombre}/><span><ImageIcon size={15}/>Ver fotos</span></button><div>{(n.galeria||[n.imagen,imagenes.hero,imagenes.plato]).slice(1,3).map((im,i)=><button key={i} onClick={()=>{setFoto(i+1);setModal({tipo:'imagen',negocio:n,indice:i+1});}} aria-label={'Ver foto '+(i+2)}><img src={im} alt={'Foto ilustrativa '+(i+2)+' de '+n.nombre}/></button>)}</div></div><div className="detalle-disposicion"><div><section className="detalle-seccion"><span className="sobretitulo">UN LUGAR CON HISTORIA</span><h2>El gusto de estar acá</h2><p>{n.descripcion} Una propuesta para disfrutar de los sabores de La Costa, reencontrarse con lo simple y compartir una buena mesa.</p><p>Dejá que la sobremesa se estire y descubrí esos pequeños detalles que hacen especial cada visita.</p><p className="aviso-demo"><CircleHelp size={15}/>Esta es una ficha de ejemplo. Las fotos son ilustrativas y los datos no corresponden a un comercio verificado.</p></section><section className="detalle-seccion"><h2>Para disfrutar a tu manera</h2><div className="servicios">{n.prestaciones.map(p=>{const I=p==='Acepta mascotas'?PawPrint:p==='Opciones vegetarianas'?Leaf:p==='Accesible'?Accessibility:p==='Mesas al aire libre'?Sun:p==='Reservas'?CalendarDays:Utensils;return <span key={p}><I size={20} strokeWidth={1.5}/>{p}</span>})}</div></section><section className="detalle-seccion" id="opiniones"><div className="titulo-seccion"><div><span className="sobretitulo">LA VOZ DE LA COMUNIDAD</span><h2>Lo que se dice por acá</h2></div><button className="boton boton-borde" onClick={()=>setModal({tipo:'opinion',negocio:n})}><Pencil size={14}/>Dejá tu opinión</button></div><div className="resumen-opiniones"><strong>{puntuacionLocal(n.valoracion)}</strong><div><span className="estrellas">{'★'.repeat(Math.round(n.valoracion))+'☆'.repeat(5-Math.round(n.valoracion))}</span><p>{n.opiniones} valoraciones de ejemplo</p></div></div>{res.length?res.map(r=><article className="opinion" key={r.id}><div className="opinion-arriba"><span className="avatar-letra">{r.nombre[0]}</span><div><strong>{r.nombre}</strong><small>{formatear(r.fecha)}</small></div><Estrellas valor={r.puntuacion}/></div><p>{r.texto}</p></article>):<p className="texto-suave">Todavía no hay reseñas publicadas para esta ficha. ¡Podés escribir la primera!</p>}</section></div><aside><div className="contacto-tarjeta"><h2>Armá tu próximo plan</h2><p>Escribile al lugar para consultar disponibilidad, su propuesta o una reserva.</p><button className="boton boton-naranja ancho" onClick={()=>setModal({tipo:'consulta',negocio:n})}><MessageSquare size={17}/>Consultar al lugar</button><small className="texto-centro">Demostración · No se envían mensajes reales</small><hr/><div className="dato-contacto"><MapPin size={19}/><div><strong>Dónde estamos</strong><span>{n.direccion}<br/>{n.localidad}, La Costa</span><a href={'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(n.localidad+', Partido de La Costa, Buenos Aires')} target="_blank" rel="noreferrer">Explorar la localidad <ArrowUpRight size={12}/></a></div></div><div className="dato-contacto"><Clock size={19}/><div><strong>Horarios de ejemplo</strong><span>{n.horarios}</span></div></div><div className="dato-contacto"><Mail size={19}/><div><strong>Contacto</strong><span>Consultas mediante el formulario</span></div></div><div className="dato-contacto"><Utensils size={19}/><div><strong>Precio orientativo</strong><span>{'$'.repeat(n.precio)} · {['','Económico','Precio intermedio','Una ocasión especial'][n.precio]}</span></div></div></div><div className="reclamar-tarjeta"><Store size={23}/><h3>¿Este es tu negocio?</h3><p>Reclamá tu ficha y mantené tu información al día.</p><Enlace to={'/reclamar?lugar='+n.slug}>Reclamar este lugar <ArrowRight size={15}/></Enlace></div></aside></div>{relacionados.length>0&&<section className="seccion"><div className="titulo-seccion"><div><span className="sobretitulo">SEGUÍ DESCUBRIENDO</span><h2>También te pueden gustar</h2></div><Enlace to={'/categoria/'+n.categoria} className="enlace-flecha">Ver más <ArrowRight size={17}/></Enlace></div><div className="grilla-tarjetas">{relacionados.map(n=><Tarjeta key={n.id} negocio={n}/>)}</div></section>}</main>}
function Guardados(){const {favoritos,listado}=usar();const favoritosLista=listado.filter(n=>favoritos.includes(n.id)&&n.estado==='aprobado');return <main className="contenedor pagina"><Migas items={[{texto:'Mis guardados'}]}/><div className="encabezado-pagina"><span className="sobretitulo">PARA VOLVER CUANDO QUIERAS</span><h1>Tu lista de buenos planes.</h1><p>Esos lugares que te gustaron, todos juntos. Se guardan en este navegador.</p></div>{favoritosLista.length?<div className="grilla-tarjetas">{favoritosLista.map(n=><Tarjeta key={n.id} negocio={n}/>)}</div>:<Vacio icono={Heart} titulo="Tu próximo favorito te está esperando" texto="Tocá el corazón de un lugar para sumarlo a tu lista y encontrarlo fácilmente después."><Enlace to="/explorar" className="boton boton-naranja">Descubrir lugares <ArrowRight size={16}/></Enlace></Vacio>}</main>}
function FormularioNegocio({editar=null,alGuardar}){const categorias=usarCategorias();const {guardarNegocio,notificar,usuario,modoDemo}=usar();const [valor,setValor]=useState(editar||{nombre:'',categoria:'restaurantes',localidad:'San Bernardo',direccion:'',descripcion:'',precio:2,prestaciones:[],horarios:'',contacto_email:'',telefono:'',web:''});const [ocupado,setOcupado]=useState(false);const actualizar=(k,v)=>setValor({...valor,[k]:v});async function enviar(e){e.preventDefault();setOcupado(true);try{const resultado=await guardarNegocio(valor,!!editar);if(resultado){notificar(editar?'Cambios guardados. La ficha está pendiente de revisión.':'¡Recibimos tu lugar! Ahora está pendiente de aprobación.');alGuardar?.();}}catch(err){notificar(traducirError(err),'error')}finally{setOcupado(false)}}return <form className="formulario" onSubmit={enviar}><h2>{editar?'Los datos de tu lugar':'Empecemos por lo esencial'}</h2><div className="dos-campos"><label>Nombre del negocio<input required minLength={2} maxLength={100} value={valor.nombre} onChange={e=>actualizar('nombre',e.target.value)} placeholder="Ej.: Café de la Costa"/></label><label>Categoría<select value={valor.categoria} onChange={e=>actualizar('categoria',e.target.value)}>{categorias.map(c=><option value={c.id} key={c.id}>{c.nombre}</option>)}</select></label></div><div className="dos-campos"><label>Localidad<select value={valor.localidad} onChange={e=>actualizar('localidad',e.target.value)}>{localidades.map(l=><option key={l}>{l}</option>)}</select></label><label>Dirección<input required value={valor.direccion} onChange={e=>actualizar('direccion',e.target.value)} placeholder="Calle y número" maxLength={180}/></label></div><label>Contanos sobre tu propuesta<textarea required minLength={20} maxLength={1200} rows={4} value={valor.descripcion} onChange={e=>actualizar('descripcion',e.target.value)} placeholder="Qué hace especial a tu lugar, qué se puede comer y cómo es el ambiente..."/><small>Entre 20 y 1.200 caracteres.</small></label><div className="dos-campos"><label>Precio por persona<select value={valor.precio} onChange={e=>actualizar('precio',Number(e.target.value))}><option value={1}>$ · Económico</option><option value={2}>$$ · Intermedio</option><option value={3}>$$$ · Una ocasión especial</option></select></label><label>Horarios<input required maxLength={160} value={valor.horarios} onChange={e=>actualizar('horarios',e.target.value)} placeholder="Ej.: Martes a domingo, de 12 a 23"/></label></div><h3>Cómo pueden encontrarte</h3><div className="dos-campos"><label>Correo de contacto<input type="email" required value={valor.contacto_email||''} onChange={e=>actualizar('contacto_email',e.target.value)} placeholder="hola@tulugar.com.ar"/></label><label>Teléfono<input type="tel" maxLength={30} value={valor.telefono||''} onChange={e=>actualizar('telefono',e.target.value)} placeholder="Opcional · Código de área y número"/></label></div><label>Sitio web<input type="url" maxLength={300} value={valor.web||''} onChange={e=>actualizar('web',e.target.value)} placeholder="Opcional · https://..."/></label><fieldset><legend>Servicios y comodidades</legend><div className="checkbox-grilla">{prestaciones.map(p=><label className="checkbox" key={p}><input type="checkbox" checked={valor.prestaciones.includes(p)} onChange={()=>actualizar('prestaciones',valor.prestaciones.includes(p)?valor.prestaciones.filter(x=>x!==p):[...valor.prestaciones,p])}/>{p}</label>)}</div></fieldset><p className="aviso-demo"><ImageIcon size={17}/>La ficha de demostración utiliza fotos ilustrativas. La gestión de imágenes propias se habilita al conectar Supabase Storage.</p><label className="checkbox"><input type="checkbox" required/>Confirmo que puedo representar a este negocio y que los datos son correctos.</label><div className="formulario-pie"><span><ShieldCheck size={15}/>Cada ficha pasa por una revisión.</span><button disabled={ocupado} className="boton boton-naranja">{ocupado?'Guardando...':editar?'Guardar cambios':'Enviar mi lugar'}<ArrowRight size={16}/></button></div></form>}
function SumarLugar(){const {ir,usuario}=usar();return <main className="contenedor pagina"><Migas items={[{texto:'Sumá tu lugar'}]}/><div className="encabezado-pagina"><span className="sobretitulo">HAGAMOS CRECER LOS BUENOS PLANES</span><h1>Tu lugar merece ser descubierto.</h1><p>Presentá tu propuesta y conectá con quienes quieren comer rico en La Costa.</p></div><div className="disposicion-formulario"><FormularioNegocio alGuardar={()=>ir('/mi-negocio')}/><aside className="consejos"><span className="icono-caja"><Store size={29}/></span><h2>Lo local se comparte.</h2><p>Un espacio para los lugares que hacen especial a nuestra Costa.</p>{['Una ficha con toda tu información','Presencia en búsquedas por localidad','Consultas en un solo lugar','Un panel para mantenerte al día'].map(t=><p className="consejo" key={t}><CheckCircle2 size={17}/>{t}</p>)}<hr/><h3>¿Tu negocio ya aparece?</h3><p>Podés reclamar su ficha y actualizar sus datos.</p><Enlace to="/reclamar" className="enlace-flecha">Reclamar mi lugar <ArrowRight size={16}/></Enlace><p className="nota-muestra">Modo demostración: las solicitudes se guardan solo en este navegador.</p></aside></div></main>}
function Reclamar(){const {ruta,listado,guardarReclamo,notificar,ir}=usar();const elegido=new URLSearchParams(ruta.split('?')[1]).get('lugar');const [enviado,setEnviado]=useState(false);async function enviar(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await guardarReclamo(d);setEnviado(true)}catch(err){notificar(traducirError(err),'error')}}return <main className="contenedor pagina"><Migas items={[{texto:'Reclamar mi negocio'}]}/><div className="encabezado-pagina"><span className="sobretitulo">TU HISTORIA, CONTADA POR VOS</span><h1>Tomá las riendas de tu ficha.</h1><p>Verificamos cada solicitud para cuidar la información de la comunidad.</p></div><div className="formulario-angosto">{enviado?<Vacio icono={CheckCircle2} titulo="Tu solicitud ya está en camino" texto="Guardamos tu solicitud de demostración. Podés ver su estado desde el panel de tu negocio."><Enlace to="/mi-negocio" className="boton boton-naranja">Ir a mi panel</Enlace></Vacio>:<form className="formulario" onSubmit={enviar}><label>¿Qué negocio querés reclamar?<select name="negocio_id" required defaultValue={listado.find(n=>n.slug===elegido)?.id||''}><option value="" disabled>Elegí tu negocio</option>{listado.map(n=><option key={n.id} value={n.id}>{n.nombre} · {n.localidad}</option>)}</select></label><div className="dos-campos"><label>Tu nombre completo<input name="nombre" required maxLength={100}/></label><label>Tu correo de contacto<input name="email" required type="email"/></label></div><label>Tu relación con el negocio<select name="relacion" required><option>Propietario o propietaria</option><option>Responsable de administración</option><option>Representante autorizado</option></select></label><label>Contanos cómo podemos verificarlo<textarea name="verificacion" required minLength={20} maxLength={1000} rows={4} placeholder="Por ejemplo, un sitio oficial, un correo del negocio o un perfil público donde figure tu función."/></label><label className="checkbox"><input type="checkbox" required/>Confirmo que estoy autorizado para representar este negocio.</label><p className="aviso-demo"><ShieldCheck size={17}/>La solicitud requiere revisión. Reclamar una ficha no te da acceso automático a ella.</p><button className="boton boton-naranja ancho">Enviar solicitud <ArrowRight size={16}/></button></form>}</div></main>}
function Ingresar(){const {ir,setModoDemo,notificar,usuario}=usar();const [registro,setRegistro]=useState(false);const [ocupado,setOcupado]=useState(false);async function enviar(e){e.preventDefault();if(!supabase){notificar('La conexión con Supabase está pendiente. Podés recorrer el panel de demostración.');return}setOcupado(true);const d=Object.fromEntries(new FormData(e.currentTarget));const {error}=registro?await supabase.auth.signUp({email:d.email,password:d.password}):await supabase.auth.signInWithPassword({email:d.email,password:d.password});setOcupado(false);if(error)notificar(traducirError(error),'error');else if(registro)notificar('Revisá tu correo para confirmar la cuenta.');else ir('/mi-negocio')}return <main className="contenedor pagina acceso-pagina"><div className="acceso-presentacion"><span className="sobretitulo">UN LUGAR PARA TU LUGAR</span><h1>La buena cocina<br/>merece <em>encontrarse.</em></h1><p>Administrá tu ficha, actualizá tu propuesta y recibí las consultas de tus próximos visitantes.</p><Waves size={70} strokeWidth={1}/></div><div className="formulario"><h2>{registro?'Creá tu cuenta':'Qué bueno verte por acá.'}</h2><p>{registro?'Empezá a compartir tu propuesta.':'Ingresá para administrar tu negocio.'}</p>{!conectado&&<div className="aviso-demo"><CircleHelp size={17}/>El acceso con cuenta estará disponible al conectar Supabase. Mientras tanto, podés probar el panel.</div>}<form onSubmit={enviar}><label>Correo electrónico<input required type="email" name="email" autoComplete="email" placeholder="tu@correo.com"/></label><label>Contraseña<input required type="password" name="password" minLength={8} autoComplete={registro?'new-password':'current-password'} placeholder="Al menos 8 caracteres"/></label><button className="boton boton-naranja ancho" disabled={ocupado}>{ocupado?'Un momento...':registro?'Crear cuenta':'Ingresar'}<ArrowRight size={16}/></button></form><button className="boton-texto centrado" onClick={()=>setRegistro(!registro)}>{registro?'Ya tengo una cuenta':'¿Primera vez? Creá tu cuenta'}</button><div className="separador"><span>O conocé cómo funciona</span></div><button className="boton boton-borde ancho" onClick={()=>{setModoDemo(true);ir('/mi-negocio')}}><Eye size={17}/>Explorar panel de demostración</button></div></main>}
function PanelPropietario(){const {usuario,modoDemo,setModoDemo,ir,datos,listado,cerrarSesion,setModal}=usar();const [pestana,setPestana]=useState('negocios');const [editar,setEditar]=useState(null);const propios=conectado?listado.filter(n=>n.owner_id===usuario?.id):datos.negocios.filter(n=>n.propietario_demo||!negocios.some(b=>b.id===n.id));const consultas=datos.consultas;return <main className="contenedor pagina"><div className="panel-titulo"><div><span className="sobretitulo">TU NEGOCIO, BIEN ACOMPAÑADO</span><h1>Mi panel</h1><p>Todo lo que necesitás para contar tu propuesta.</p></div><div className="panel-acciones"><span className="etiqueta-demo">{conectado?'Cuenta de propietario':'Modo demostración'}</span>{usuario&&<button className="boton boton-borde" onClick={cerrarSesion}><LogOut size={15}/>Salir</button>}</div></div>{!conectado&&!modoDemo&&<div className="aviso-demo"><Eye size={18}/><span>Estás recorriendo una demostración. Los cambios se guardan en este navegador.</span><button className="boton-texto" onClick={()=>setModoDemo(true)}>Entendido</button></div>}<div className="metricas"><Metrica icono={Store} valor={propios.length} texto="Mis lugares"/><Metrica icono={MessageSquare} valor={consultas.length} texto="Consultas recibidas"/><Metrica icono={Clock} valor={propios.filter(n=>n.estado==='pendiente').length+datos.reclamos.filter(r=>r.estado==='pendiente').length} texto="Solicitudes pendientes"/></div><div className="pestanas" role="tablist" aria-label="Secciones de mi panel">{[['negocios','Mis lugares',Store],['consultas','Bandeja de consultas',MessageSquare],['solicitudes','Mis solicitudes',ShieldCheck]].map(([id,t,I])=><button key={id} role="tab" aria-selected={pestana===id} onClick={()=>{setPestana(id);setEditar(null)}} className={pestana===id?'activa':''}><I size={16}/>{t}</button>)}</div>{pestana==='negocios'&&(editar?<><button className="boton-texto" onClick={()=>setEditar(null)}><ArrowLeft size={15}/>Volver a mis lugares</button><FormularioNegocio editar={editar} alGuardar={()=>setEditar(null)}/></>:<><div className="panel-subtitulo"><h2>Los lugares que administrás</h2><Enlace className="boton boton-naranja" to="/sumar-lugar"><Plus size={16}/>Sumar un lugar</Enlace></div>{propios.length?<div className="lista-gestion">{propios.map(n=><div className="fila-gestion" key={n.id}><img src={n.imagen} alt=""/><div><h3>{n.nombre}</h3><p>{n.localidad}</p></div><Estado valor={n.estado}/><button className="boton boton-borde" onClick={()=>setEditar(n)}><Pencil size={14}/>Editar</button></div>)}</div>:<Vacio icono={Store} titulo="Tu lugar empieza acá" texto="Sumá tu negocio al directorio o reclamá una ficha existente para administrarla."><div className="botones-juntos"><Enlace to="/sumar-lugar" className="boton boton-naranja">Sumar mi lugar</Enlace><Enlace to="/reclamar" className="boton boton-borde">Reclamar una ficha</Enlace></div></Vacio>}</>)}{pestana==='consultas'&&(consultas.length?<div className="lista-gestion">{consultas.map(c=><article className="consulta" key={c.id}><div><strong>{c.nombre}</strong><span>{c.email}</span><Estado valor={c.estado||'nueva'}/></div><h3>{listado.find(n=>n.id===c.negocio_id)?.nombre}</h3><p>{c.mensaje}</p><small>Consulta de demostración · {formatear(c.fecha)}</small></article>)}</div>:<Vacio icono={Mail} titulo="Acá comienzan nuevos encuentros" texto="Las consultas de tus próximos visitantes aparecerán en esta bandeja. La recepción real se activa al conectar Supabase."><Enlace to="/explorar" className="boton boton-borde">Explorar el directorio</Enlace></Vacio>)}{pestana==='solicitudes'&&(datos.reclamos.length?<div className="lista-gestion">{datos.reclamos.map(r=><div className="fila-gestion" key={r.id}><ShieldCheck size={24}/><div><h3>{listado.find(n=>n.id===r.negocio_id)?.nombre}</h3><p>Solicitud de titularidad · {r.nombre}</p></div><Estado valor={r.estado}/></div>)}</div>:<Vacio icono={ShieldCheck} titulo="Todo en orden por acá" texto="Cuando reclames una ficha, vas a poder seguir el estado de tu solicitud desde este espacio."><Enlace to="/reclamar" className="boton boton-borde">Reclamar mi negocio</Enlace></Vacio>)}</main>}
function Estado({valor}){return <span className={'estado estado-'+valor}>{({aprobado:'Aprobado',pendiente:'Pendiente de revisión',rechazado:'Rechazado',nueva:'Nueva consulta'})[valor]||valor}</span>}
function Metrica({icono:I,valor,texto}){return <div className="metrica"><span><I size={22} strokeWidth={1.5}/></span><div><strong>{valor}</strong><small>{texto}</small></div></div>}
function Administracion(){const todasCategorias=usarCategorias();const {listado,opiniones,datos,modificarNegocio,modificarOpinion,modificarReclamo,agregarCategoria,quitarCategoria,usuario,notificar}=usar();const [pestana,setPestana]=useState('lugares');const [buscar,setBuscar]=useState('');const esAdmin=!conectado||usuario?.app_metadata?.role==='admin';if(!esAdmin)return <main className="contenedor pagina"><Vacio icono={ShieldCheck} titulo="Un espacio reservado" texto="Necesitás una cuenta de administración para acceder a esta sección."><Enlace to="/ingresar" className="boton boton-naranja">Ingresar a mi cuenta</Enlace></Vacio></main>;const disponibles=listado.filter(n=>n.nombre.toLowerCase().includes(buscar.toLowerCase()));const nuevas=datos.categorias;return <main className="contenedor pagina"><div className="panel-titulo"><div><span className="sobretitulo">CUIDAMOS LA EXPERIENCIA ENTRE TODOS</span><h1>Administración</h1><p>Revisá propuestas y mantené el directorio al día.</p></div><span className="etiqueta-demo">{conectado?'Administración':'Administración de demostración'}</span></div>{!conectado&&<div className="aviso-demo"><ShieldCheck size={18}/>Este panel es una simulación local. Al conectar Supabase, solo las cuentas con rol de administración podrán acceder.</div>}<div className="metricas cuatro"><Metrica icono={Store} valor={listado.length} texto="Lugares en el directorio"/><Metrica icono={Clock} valor={listado.filter(n=>n.estado==='pendiente').length} texto="Esperando aprobación"/><Metrica icono={Star} valor={listado.filter(n=>n.destacado).length} texto="Lugares destacados"/><Metrica icono={MessageSquare} valor={opiniones.filter(r=>r.estado==='pendiente').length} texto="Reseñas por revisar"/></div><div className="pestanas" role="tablist" aria-label="Secciones de administración">{[['lugares','Lugares'],['categorias','Categorías'],['opiniones','Reseñas'],['reclamos','Titularidades']].map(([id,t])=><button key={id} role="tab" aria-selected={id===pestana} className={id===pestana?'activa':''} onClick={()=>setPestana(id)}>{t}</button>)}</div>{pestana==='lugares'&&<><div className="panel-subtitulo"><h2>Aprobación y destacados</h2><div className="buscador-mini"><Search size={16}/><input aria-label="Buscar negocio para administrar" value={buscar} onChange={e=>setBuscar(e.target.value)} placeholder="Buscar un lugar..."/></div></div><div className="tabla-contenedor"><table><thead><tr><th>Lugar</th><th>Localidad</th><th>Estado</th><th>Destacado</th><th>Acciones</th></tr></thead><tbody>{disponibles.map(n=><tr key={n.id}><td><div className="negocio-tabla"><img src={n.imagen} alt=""/><div><strong>{n.nombre}</strong><small>{categorias.find(c=>c.id===n.categoria)?.nombre}</small></div></div></td><td>{n.localidad}</td><td><Estado valor={n.estado}/></td><td><button className={'boton-destacar '+(n.destacado?'activo':'')} aria-pressed={n.destacado} aria-label={(n.destacado?'Quitar destacado a ':'Destacar ')+n.nombre} onClick={()=>modificarNegocio(n.id,{destacado:!n.destacado})}><Star size={17} fill={n.destacado?'currentColor':'none'}/>{n.destacado?'Destacado':'Destacar'}</button></td><td><div className="acciones-fila">{n.estado!=='aprobado'&&<button onClick={()=>modificarNegocio(n.id,{estado:'aprobado'})} className="boton-aprobar"><Check size={14}/>Aprobar</button>}{n.estado!=='rechazado'&&<button className="boton-texto peligro" onClick={()=>modificarNegocio(n.id,{estado:'rechazado'})}>Rechazar</button>}{n.estado==='aprobado'&&<Enlace to={'/lugar/'+n.slug} aria-label={'Ver '+n.nombre}><ArrowUpRight size={17}/></Enlace>}</div></td></tr>)}</tbody></table>{!disponibles.length&&<p className="texto-centro">No hay lugares que coincidan con la búsqueda.</p>}</div></>}{pestana==='categorias'&&<><div className="panel-subtitulo"><h2>Categorías del directorio</h2></div><form className="formulario-categoria" onSubmit={e=>{e.preventDefault();const nombre=new FormData(e.currentTarget).get('nombre').trim();if(nombre){agregarCategoria(nombre);e.currentTarget.reset();}}}><input name="nombre" required minLength={3} maxLength={60} placeholder="Nombre de la nueva categoría" aria-label="Nombre de la nueva categoría"/><button className="boton boton-naranja"><Plus size={16}/>Agregar categoría</button></form><div className="lista-gestion">{todasCategorias.map(c=><div className="fila-gestion" key={c.id}><IconoCategoria id={c.id} size={23}/><div><h3>{c.nombre}</h3><p>{listado.filter(n=>n.categoria===c.id).length} lugares asociados</p></div>{nuevas.some(x=>x.id===c.id)?<button className="boton-texto peligro" onClick={()=>quitarCategoria(c.id)} aria-label={'Eliminar '+c.nombre}><Trash2 size={17}/>Eliminar</button>:<span className="etiqueta-base">Categoría base</span>}</div>)}</div><p className="nota-muestra">Las categorías base se conservan para mantener las fichas y los enlaces existentes. Las categorías nuevas ya están disponibles en el formulario y en la búsqueda.</p></>}{pestana==='opiniones'&&<><div className="panel-subtitulo"><h2>Moderación de reseñas</h2></div>{opiniones.length?<div className="lista-gestion">{opiniones.map(r=><article className="opinion opinion-admin" key={r.id}><div className="opinion-arriba"><span className="avatar-letra">{r.nombre[0]}</span><div><strong>{r.nombre} · {listado.find(n=>n.id===r.negocio_id)?.nombre}</strong><small>{formatear(r.fecha)}</small></div><Estado valor={r.estado}/></div><p>{r.texto}</p><div className="acciones-fila">{r.estado!=='aprobado'&&<button className="boton-aprobar" onClick={()=>modificarOpinion(r.id,'aprobado')}><Check size={14}/>Publicar reseña</button>}{r.estado!=='rechazado'&&<button className="boton-texto peligro" onClick={()=>modificarOpinion(r.id,'rechazado')}>Ocultar reseña</button>}</div></article>)}</div>:<Vacio titulo="Sin reseñas por revisar" texto="Las reseñas enviadas desde las fichas aparecen en este espacio."/>}</>}{pestana==='reclamos'&&<><div className="panel-subtitulo"><h2>Solicitudes de titularidad</h2></div>{datos.reclamos.length?<div className="lista-gestion">{datos.reclamos.map(r=><article className="consulta" key={r.id}><div><strong>{r.nombre}</strong><span>{r.email}</span><Estado valor={r.estado}/></div><h3>{listado.find(n=>n.id===r.negocio_id)?.nombre}</h3><p>{r.relacion} · {r.verificacion}</p><div className="acciones-fila">{r.estado==='pendiente'&&<><button className="boton-aprobar" onClick={()=>modificarReclamo(r.id,'aprobado')}><Check size={14}/>Aprobar titularidad</button><button className="boton-texto peligro" onClick={()=>modificarReclamo(r.id,'rechazado')}>Rechazar</button></>}</div></article>)}</div>:<Vacio icono={ShieldCheck} titulo="No hay solicitudes pendientes" texto="Las solicitudes para reclamar un negocio aparecerán acá para su verificación."/>}</>}</main>}
function Informacion({tipo}){return <main className="contenedor pagina"><Migas items={[{texto:tipo==='costa'?'Nuestra Costa':'Cómo funciona'}]}/><div className="pagina-editorial"><span className="sobretitulo">HECHO CON AMOR POR LO LOCAL</span><h1>{tipo==='costa'?<>El mar nos reúne.<br/>La mesa, también.</>:'Un buen plan empieza acá.'}</h1><p className="bajada">{tipo==='costa'?'Un directorio para descubrir los sabores del Partido de La Costa, sus localidades y las historias que se cocinan en cada rincón.':'Encontrá tu próximo lugar favorito, guardalo para después y conectá con su propuesta.'}</p>{tipo==='costa'?<><img className="foto-editorial" src={imagenes.hero} alt="Un espacio gastronómico cálido y luminoso"/><h2>Mucho más que una escapada</h2><p>Desde San Clemente del Tuyú hasta Nueva Atlantis, La Costa tiene cafés para una tarde de lluvia, mesas para una celebración, parrillas de barrio y helados para caminar frente al mar. Queremos que encontrarlos sea parte del disfrute.</p><h2>Un espacio que crece con su comunidad</h2><p>Los negocios pueden sumar su propuesta y mantenerla al día. Quienes visitan el directorio pueden explorar por localidad, comparar opciones y compartir su experiencia.</p></>:<div className="pasos">{[['01','Buscá a tu manera','Elegí lo que tenés ganas de comer y por dónde querés ir. Los filtros te ayudan a encontrar un lugar para cada plan.'],['02','Conocé cada propuesta','Explorá las fotos, los servicios y las reseñas de cada lugar. Guardá tus favoritos para volver a encontrarlos.'],['03','Hacé tu consulta','Usá el formulario de la ficha para preguntar por disponibilidad o conocer más sobre la propuesta.']].map(([n,t,d])=><div key={n}><span>{n}</span><h2>{t}</h2><p>{d}</p></div>)}</div>}<div className="aviso-demo"><CircleHelp size={20}/><p>Esta primera edición es una demostración. Los 20 negocios, sus direcciones y valoraciones son ficticios; las fotos son ilustrativas. Las consultas y solicitudes quedan en este navegador hasta conectar Supabase.</p></div><Enlace to="/explorar" className="boton boton-naranja">Empezá a descubrir <ArrowRight size={16}/></Enlace></div></main>}
function NoEncontrado(){return <main className="contenedor pagina"><Vacio icono={Compass} titulo="Por acá todavía no hay mesa" texto="No encontramos esa página. Volvé al directorio para seguir descubriendo lugares."><Enlace to="/explorar" className="boton boton-naranja">Explorar lugares</Enlace></Vacio></main>}
function VentanaModal(){const {modal,setModal,guardarConsulta,guardarOpinion,notificar}=usar();const [ocupado,setOcupado]=useState(false);const [puntuacion,setPuntuacion]=useState(5);const [enviado,setEnviado]=useState(false);const ref=useRef(null);useEffect(()=>{const antes=document.activeElement;ref.current?.focus();const manejar=e=>{if(e.key==='Escape')setModal(null);if(e.key==='Tab'){const elementos=ref.current?.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]');if(!elementos?.length)return;const primero=elementos[0],ultimo=elementos[elementos.length-1];if(e.shiftKey&&document.activeElement===primero){e.preventDefault();ultimo.focus()}else if(!e.shiftKey&&document.activeElement===ultimo){e.preventDefault();primero.focus()}}};document.addEventListener('keydown',manejar);const overflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',manejar);document.body.style.overflow=overflow;antes?.focus()}},[]);if(!modal)return null;const n=modal.negocio;async function enviar(e){e.preventDefault();setOcupado(true);const d=Object.fromEntries(new FormData(e.currentTarget));try{if(modal.tipo==='consulta')await guardarConsulta({...d,negocio_id:n.id});else await guardarOpinion({...d,negocio_id:n.id,puntuacion});setEnviado(true)}catch(err){notificar(traducirError(err),'error')}finally{setOcupado(false)}}return <div className="modal-fondo" onClick={e=>{if(e.target===e.currentTarget)setModal(null)}}><section className={'modal '+(modal.tipo==='imagen'?'modal-imagen':'')} role="dialog" aria-modal="true" aria-label={modal.tipo==='imagen'?'Galería de '+n.nombre:modal.tipo==='consulta'?'Consulta a '+n.nombre:'Reseña de '+n.nombre} tabIndex={-1} ref={ref}><button className="cerrar-modal" aria-label="Cerrar ventana" onClick={()=>setModal(null)}><X size={21}/></button>{modal.tipo==='imagen'?<><h2 id="titulo-modal">{n.nombre}</h2><img src={n.galeria?.[modal.indice]||n.imagen} alt={'Foto ilustrativa de '+n.nombre}/><div className="miniaturas">{(n.galeria||[n.imagen]).map((im,i)=><button key={i} className={i===modal.indice?'activa':''} aria-label={'Mostrar foto '+(i+1)} onClick={()=>setModal({...modal,indice:i})}><img src={im} alt=""/></button>)}</div><small>Fotos ilustrativas de demostración</small></>:enviado?<Vacio icono={CheckCircle2} titulo={modal.tipo==='consulta'?'¡Consulta guardada!':'Gracias por compartir tu experiencia'} texto={modal.tipo==='consulta'?'Tu consulta de demostración está guardada en la bandeja del panel. No se envió ningún mensaje real.':'Tu reseña quedó pendiente de moderación. Podés revisarla desde la administración de demostración.'}><button className="boton boton-naranja" onClick={()=>setModal(null)}>Listo</button></Vacio>:<><span className="sobretitulo">{n.nombre}</span><h2 id="titulo-modal">{modal.tipo==='consulta'?'Tu próximo plan empieza acá.':'Tu experiencia suma.'}</h2><p>{modal.tipo==='consulta'?'Consultá sobre la propuesta o la disponibilidad del lugar.':'Contanos cómo fue tu visita para ayudar a otras personas.'}</p><form className="formulario-modal" onSubmit={enviar}><label>Tu nombre<input name="nombre" required minLength={2} maxLength={100}/></label>{modal.tipo==='consulta'?<><label>Tu correo<input name="email" type="email" required/></label><label>¿En qué podemos ayudarte?<textarea name="mensaje" required minLength={10} maxLength={2000} rows={4} placeholder="Contanos tu consulta..."/></label></>:<><fieldset className="elegir-estrellas"><legend>Tu valoración</legend>{[1,2,3,4,5].map(v=><button type="button" key={v} aria-label={v+' '+(v===1?'estrella':'estrellas')} aria-pressed={puntuacion===v} onClick={()=>setPuntuacion(v)}><Star fill={v<=puntuacion?'currentColor':'none'} size={29}/></button>)}</fieldset><label>Tu experiencia<textarea name="texto" required minLength={20} maxLength={1500} rows={4} placeholder="Qué te gustó, qué recomendarías..."/></label></>}<label className="checkbox"><input type="checkbox" required/>{modal.tipo==='consulta'?'Acepto compartir estos datos con el negocio para responder mi consulta.':'Confirmo que la reseña refleja mi experiencia y acepto su moderación.'}</label><p className="nota-muestra">Modo demostración · Se guarda solo en este navegador.</p><button className="boton boton-naranja ancho" disabled={ocupado}>{ocupado?'Guardando...':modal.tipo==='consulta'?'Guardar consulta de prueba':'Enviar mi reseña'}<Send size={15}/></button></form></>}</section></div>}

export default function App({rutaInicial='/'}){
 const [ruta,setRuta]=useState(rutaInicial);const [datos,setDatos]=useState(vacios);const [favoritos,setFavoritos]=useState([]);const [cargado,setCargado]=useState(false);const [modal,setModal]=useState(null);const [aviso,setAviso]=useState(null);const [usuario,setUsuario]=useState(null);const [modoDemo,setModoDemo]=useState(false);const [remotos,setRemotos]=useState([]);const [resenasRemotas,setResenasRemotas]=useState([]);const [categoriasRemotas,setCategoriasRemotas]=useState([]);const temporizador=useRef(null);
 const notificar=(texto,tipo='exito')=>{setAviso({texto,tipo});clearTimeout(temporizador.current);temporizador.current=setTimeout(()=>setAviso(null),6000)};
 useEffect(()=>{try{const guardado=JSON.parse(localStorage.getItem('costa-datos-v1')||'null');if(guardado&&Array.isArray(guardado.negocios))setDatos({...vacios,...guardado});const fav=JSON.parse(localStorage.getItem('costa-favoritos-v1')||'[]');if(Array.isArray(fav))setFavoritos(fav);setModoDemo(localStorage.getItem('costa-demo')==='si')}catch{}setCargado(true);const pop=()=>setRuta(location.pathname+location.search);window.addEventListener('popstate',pop);setRuta(location.pathname+location.search);const invalidar=e=>{const t=e.target;if(!t.validity)return;t.setCustomValidity('');const v=t.validity;if(v.valueMissing)t.setCustomValidity(t.type==='checkbox'?'Marcá esta casilla para continuar.':'Completá este campo para continuar.');else if(v.typeMismatch)t.setCustomValidity(t.type==='email'?'Ingresá un correo electrónico válido.':'Ingresá una dirección web válida que comience con https://.');else if(v.tooShort)t.setCustomValidity('Escribí al menos '+t.minLength+' caracteres.');else if(!v.valid)t.setCustomValidity('Revisá el valor de este campo.');};const limpiarValidez=e=>e.target.setCustomValidity?.('');document.addEventListener('invalid',invalidar,true);document.addEventListener('input',limpiarValidez,true);return()=>{window.removeEventListener('popstate',pop);document.removeEventListener('invalid',invalidar,true);document.removeEventListener('input',limpiarValidez,true);clearTimeout(temporizador.current)}},[]);
 useEffect(()=>{if(cargado){try{localStorage.setItem('costa-datos-v1',JSON.stringify(datos));localStorage.setItem('costa-favoritos-v1',JSON.stringify(favoritos));localStorage.setItem('costa-demo',modoDemo?'si':'no')}catch{notificar('El navegador no permite guardar cambios. Revisá el espacio disponible.','error')}}},[datos,favoritos,modoDemo,cargado]);
 useEffect(()=>{if(!supabase)return;supabase.auth.getSession().then(({data})=>setUsuario(data.session?.user||null));const {data}=supabase.auth.onAuthStateChange((_evento,sesion)=>setUsuario(sesion?.user||null));return()=>data.subscription.unsubscribe()},[]);
 const recargar=async()=>{if(!supabase)return;const [{data,error},{data:reviews},{data:cats},{data:leads},{data:claims}]=await Promise.all([supabase.from('listings').select('*'),supabase.from('reviews').select('*'),supabase.from('categories').select('*'),supabase.from('leads').select('*'),supabase.from('listing_claims').select('*')]);if(error){notificar('No se pudo cargar el directorio. Revisá la configuración de Supabase.','error');return}setRemotos(data||[]);setResenasRemotas(reviews||[]);setCategoriasRemotas(cats||[]);setDatos(prev=>({...prev,consultas:leads||[],reclamos:claims||[],categorias:(cats||[]).filter(c=>!categorias.some(b=>b.id===c.id))}))};
 useEffect(()=>{recargar()},[usuario]);
 const todasCategorias=conectado?categoriasRemotas:[...categorias,...datos.categorias];
 const listadoBase=conectado?remotos:[...negocios.map(n=>({...n,...datos.negocios.find(d=>d.id===n.id)})),...datos.negocios.filter(n=>!negocios.some(b=>b.id===n.id))];
 const opiniones=conectado?resenasRemotas:[...opinionesIniciales.map(r=>({...r,...datos.opiniones.find(d=>d.id===r.id)})),...datos.opiniones.filter(r=>!opinionesIniciales.some(b=>b.id===r.id))];
 const listado=conectado?listadoBase:listadoBase.map(n=>{const base=negocios.find(b=>b.id===n.id);const extras=opiniones.filter(r=>r.negocio_id===n.id&&r.estado==='aprobado'&&!opinionesIniciales.some(b=>b.id===r.id));const ocultas=opinionesIniciales.filter(r=>r.negocio_id===n.id&&opiniones.find(b=>b.id===r.id)?.estado!=='aprobado');const cantidad=Math.max(0,(base?.opiniones||0)+extras.length-ocultas.length);const puntos=(base?.valoracion||0)*(base?.opiniones||0)+extras.reduce((s,r)=>s+r.puntuacion,0)-ocultas.reduce((s,r)=>s+r.puntuacion,0);return {...n,opiniones:cantidad,valoracion:cantidad?Math.max(0,Math.min(5,Math.round(puntos/cantidad*10)/10)):0}});
 function ir(to,subir=true){history.pushState({},'',to);setRuta(to);setModal(null);if(subir)window.scrollTo({top:0,behavior:'instant'})}
 const alternarFavorito=id=>setFavoritos(prev=>prev.includes(id)?prev.filter(x=>x!==id):[...prev,id]);
 async function guardarNegocio(valor,editar){const nuevo={...valor,id:editar?valor.id:crypto.randomUUID(),slug:editar?valor.slug:slugificar(valor.nombre)+'-'+Date.now().toString(36),estado:'pendiente',destacado:editar?valor.destacado:false,imagen:valor.imagen||imagenes.plato,galeria:valor.galeria||[imagenes.plato,imagenes.hero,imagenes.cafe],valoracion:editar?valor.valoracion:0,opiniones:editar?valor.opiniones:0};if(supabase){if(!usuario){notificar('Ingresá a tu cuenta para enviar un negocio.','error');ir('/ingresar');return false}const escritura={nombre:nuevo.nombre,slug:nuevo.slug,categoria:nuevo.categoria,localidad:nuevo.localidad,direccion:nuevo.direccion,descripcion:nuevo.descripcion,precio:nuevo.precio,prestaciones:nuevo.prestaciones,horarios:nuevo.horarios,contacto_email:nuevo.contacto_email,telefono:nuevo.telefono,web:nuevo.web,estado:'pendiente',imagen:nuevo.imagen,galeria:nuevo.galeria,owner_id:usuario.id};const {error:perfilError}=await supabase.from('owners').upsert({id:usuario.id},{onConflict:'id',ignoreDuplicates:true});if(perfilError)throw perfilError;const {error}=editar?await supabase.from('listings').update(escritura).eq('id',valor.id):await supabase.from('listings').insert(escritura);if(error)throw error;await recargar()}else setDatos(prev=>({...prev,negocios:[...prev.negocios.filter(n=>n.id!==nuevo.id),nuevo]}));return true}
 async function guardarConsulta(valor){const nueva={...valor,id:crypto.randomUUID(),fecha:new Date().toISOString().slice(0,10),estado:'nueva'};if(supabase){if(!usuario)throw {code:'42501'};const {error}=await supabase.from('leads').insert({...nueva,user_id:usuario.id});if(error)throw error}else setDatos(prev=>({...prev,consultas:[nueva,...prev.consultas]}))}
 async function guardarOpinion(valor){const nueva={...valor,id:crypto.randomUUID(),fecha:new Date().toISOString().slice(0,10),estado:'pendiente'};if(supabase){if(!usuario)throw {code:'42501'};const {error}=await supabase.from('reviews').insert({...nueva,user_id:usuario.id});if(error)throw error;await recargar()}else setDatos(prev=>({...prev,opiniones:[nueva,...prev.opiniones]}))}
 async function guardarReclamo(valor){const nuevo={...valor,id:crypto.randomUUID(),fecha:new Date().toISOString().slice(0,10),estado:'pendiente'};if(supabase){if(!usuario)throw {code:'42501'};const {error:perfilError}=await supabase.from('owners').upsert({id:usuario.id},{onConflict:'id',ignoreDuplicates:true});if(perfilError)throw perfilError;const {error}=await supabase.from('listing_claims').insert({...nuevo,user_id:usuario.id});if(error)throw error}else setDatos(prev=>({...prev,reclamos:[nuevo,...prev.reclamos]}))}
 async function modificarNegocio(id,cambios){if(supabase){const {error}=await supabase.from('listings').update(cambios).eq('id',id);if(error){notificar(traducirError(error),'error');return}await recargar()}else setDatos(prev=>({...prev,negocios:[...prev.negocios.filter(n=>n.id!==id),{...listado.find(n=>n.id===id),...cambios}]}));notificar('Ficha actualizada.');}
 async function modificarOpinion(id,estado){if(supabase){const {error}=await supabase.from('reviews').update({estado}).eq('id',id);if(error){notificar(traducirError(error),'error');return}await recargar()}else setDatos(prev=>({...prev,opiniones:[...prev.opiniones.filter(r=>r.id!==id),{...opiniones.find(r=>r.id===id),estado}]}));notificar('Reseña actualizada.');}
 async function modificarReclamo(id,estado){if(supabase){const {error}=estado==='aprobado'?await supabase.rpc('aprobar_reclamo',{reclamo_id:id}):await supabase.from('listing_claims').update({estado}).eq('id',id);if(error){notificar(traducirError(error),'error');return}await recargar()}else {const reclamo=datos.reclamos.find(r=>r.id===id);const ficha=listado.find(n=>n.id===reclamo?.negocio_id);setDatos(prev=>({...prev,reclamos:prev.reclamos.map(r=>r.id===id?{...r,estado}:r),negocios:estado==='aprobado'&&ficha?[...prev.negocios.filter(n=>n.id!==ficha.id),{...ficha,propietario_demo:true}]:prev.negocios}));}notificar('Solicitud actualizada.');}
 async function agregarCategoria(nombre){const id=slugificar(nombre);if([...categorias,...datos.categorias].some(c=>c.id===id)){notificar('Esa categoría ya existe.','error');return}if(supabase){const {error}=await supabase.from('categories').insert({id,nombre});if(error){notificar(traducirError(error),'error');return}await recargar();notificar('Categoría agregada.');return}setDatos(prev=>({...prev,categorias:[...prev.categorias,{id,nombre}]}));notificar('Categoría agregada.');}
 async function quitarCategoria(id){if(listado.some(n=>n.categoria===id)){notificar('Reasigná los negocios antes de eliminar la categoría.','error');return}if(supabase){const {error}=await supabase.from('categories').delete().eq('id',id);if(error){notificar(traducirError(error),'error');return}await recargar();notificar('Categoría eliminada.');return}setDatos(prev=>({...prev,categorias:prev.categorias.filter(c=>c.id!==id)}));notificar('Categoría eliminada.');}
 async function cerrarSesion(){if(supabase)await supabase.auth.signOut();setUsuario(null);setModoDemo(false);ir('/')}
 const path=ruta.split('?')[0].replace(/\/$/,'')||'/';let pagina;
 if(path==='/')pagina=<Inicio/>;else if(path==='/explorar')pagina=<Explorador/>;else if(path==='/categorias')pagina=<Categorias/>;else if(path.startsWith('/categoria/')&&todasCategorias.some(c=>c.id===path.split('/')[2]))pagina=<Explorador categoria={path.split('/')[2]}/>;else if(path.startsWith('/lugar/'))pagina=<Detalle slug={path.split('/')[2]}/>;else if(path==='/guardados')pagina=<Guardados/>;else if(path==='/sumar-lugar')pagina=<SumarLugar/>;else if(path==='/reclamar')pagina=<Reclamar/>;else if(path==='/ingresar')pagina=<Ingresar/>;else if(path==='/mi-negocio')pagina=conectado&&!usuario?<Ingresar/>:<PanelPropietario/>;else if(path==='/administracion')pagina=<Administracion/>;else if(path==='/sobre-la-costa')pagina=<Informacion tipo="costa"/>;else if(path==='/como-funciona')pagina=<Informacion tipo="funciona"/>;else pagina=<NoEncontrado/>;
 useEffect(()=>{const ficha=listado.find(n=>'/lugar/'+n.slug===path);const cat=categorias.find(c=>'/categoria/'+c.id===path);const titulo=ficha?ficha.nombre+' en '+ficha.localidad:cat?cat.nombre+' en La Costa':({'/explorar':'Descubrí lugares','/categorias':'Todos los sabores','/guardados':'Mis guardados','/sumar-lugar':'Sumá tu lugar','/reclamar':'Reclamar mi negocio','/ingresar':'Ingresá a tu cuenta','/mi-negocio':'Mi panel','/administracion':'Administración','/sobre-la-costa':'Nuestra Costa','/como-funciona':'Cómo funciona'})[path];document.title=(titulo?titulo+' · ':'')+'Costa a la carta';const descripcion=ficha?`${ficha.descripcion} Descubrí su propuesta en ${ficha.localidad}, La Costa.`:cat?`Descubrí ${cat.nombre.toLowerCase()} en el Partido de La Costa. Filtrá por localidad, precio y servicios.`:'Descubrí restaurantes, cafés, bares y sabores locales del Partido de La Costa.';document.querySelector('meta[name="description"]')?.setAttribute('content',descripcion)},[path]);
 const contexto={ruta,ir,datos,todasCategorias,listado,opiniones,favoritos,alternarFavorito,modal,setModal,notificar,usuario,modoDemo,setModoDemo,guardarNegocio,guardarConsulta,guardarOpinion,guardarReclamo,modificarNegocio,modificarOpinion,modificarReclamo,agregarCategoria,quitarCategoria,cerrarSesion};
 return <Contexto.Provider value={contexto}><a className="saltar" href="#contenido">Saltar al contenido</a><Cabecera/><div id="contenido">{pagina}</div><Pie/>{modal&&<VentanaModal key={modal.tipo}/>}<div className="avisos" aria-live="polite">{aviso&&<div className={'aviso '+aviso.tipo}><CheckCircle2 size={18}/><span>{aviso.texto}</span><button onClick={()=>setAviso(null)} aria-label="Cerrar aviso"><X size={16}/></button></div>}</div></Contexto.Provider>
}
